const { execSync } = require('child_process');
const videoFile = items[0].json.videoFile;
const musicFile = items[0].json.musicFile;
const quote = items[1].json.Quote;
const author = items[1].json.Author;
const outputFile = '/path/to/output/video.mp4';
execSync(`ffmpeg -i ${videoFile} -i ${musicFile} -vf "drawtext=text='${quote} - ${author}':fontfile=/path/to/Kanit.ttf:fontsize=24:fontcolor=white:x=(w-text_w)/2:y=(h-text_h)/2" -aspect 9:16 -shortest ${outputFile}`);
return [{ json: { outputFile } }];
